export function getAuthTokenAccessorsIndexQueryKey(
  args: MaybeRefOrGetter<InferRequestType<typeof client.auth.token.accessors.index.$get>>,
) {
  return ['auth', '/auth/token/accessors/', toValue(args)] as const
}

export function getAuthTokenAccessorsIndexQueryOptions(
  args: MaybeRefOrGetter<InferRequestType<typeof client.auth.token.accessors.index.$get>>,
  options?: ClientRequestOptions,
) {
  return {
    queryKey: computed(() => getAuthTokenAccessorsIndexQueryKey(args)),
    queryFn({ signal }: QueryFunctionContext) {
      return parseResponse(
        client.auth.token.accessors.index.$get(toValue(args), {
          ...options,
          init: { ...options?.init, signal },
        }),
      )
    },
  }
}

